test('live class prices read old demand before lazy network mutation, share demand and preserve variant stockpile',()=>{
 const f=networkLoadFixture(),capture=extract(f.campaign,f.descriptor),before=structuredClone(capture),live=new NativeLiveEconomyDraft(capture),m=live.market('a');
 const primary=m.commodities.luxury_goods,variant=m.commodities.lobster,demand=primary.demand,greed=primary.greed,calculator=primary.supplyPrice;
 assert.equal(primary.demand,variant.demand);assert.equal(demand,m.demandClasses.luxury_goods);
 assert.equal(primary.demandPrice.demand,Math.fround(0.1));assert.notEqual(primary.demandPrice.demand,9999);
 assert.equal(m.commodities.food.demandPrice.basePrice,1);assert.equal(m.commodities.food.demandPrice.variability,'V4');
 primary.greed.modifiers.flat.push({id:'external_margin',value:7});
 live.reapplyMarketEconomicEffects('a'); // Farming does not eagerly initialize a luxury network.
 assert.equal(live.peekCommodityData('a','luxury_goods'),null);assert.equal(primary.maxDemand,5);assert.equal(primary.maxSupply,2);
 const oldAvailable=Math.max(0,Math.floor(resolveOriginalEconomyMutable(primary.available)+0.5)),oldVariant=variant.stockpile,oldTemporary=structuredClone(primary.temporary);
 const result=live.updateStockpileAndPrice('a','luxury_goods',{month:7,phase:'native-force-stockpile-update'});
 assert.equal(result.diagnostics.noDemand,false);assert.equal(primary.maxDemand,0);assert.equal(primary.maxSupply,0);
 const primaryRow=result.commodities.find(c=>c.commodityId==='luxury_goods');
 assert.equal(primaryRow.diagnostics.icons.deficit,0);assert.equal(primary.demandPrice.highThreshold,-1);
 const F=Math.fround,unit=F(ORIGINAL_MARKET_ECONOMY.commodities.luxury_goods.econUnit),rng=originalMarketMonthlyRandom('a','luxury_goods',7);
 const expectedDemand=F(F(F(unit*5)+F(ORIGINAL_MARKET_ECONOMY.settings.economyMinStockpileForPricing*2))*F(F(0.95)+F(F(0.1)*rng.demandRoll)));
 assert.equal(result.diagnostics.rawDemand,expectedDemand);
 const network=live.peekCommodityData('a','luxury_goods'),factor=F(F(F(0.5)*10)/Math.max(3,network.data.network.exports.maxExportGlobal));
 const extra=Math.min(F(Math.min(oldAvailable,2)*factor),F(factor*10));
 const expectedStockpile=F(F(F(unit*oldAvailable)+F(unit*extra))*F(F(0.95)+F(F(0.1)*rng.stockpileRoll)));
 assert.equal(primary.stockpile,expectedStockpile);assert.equal(variant.stockpile,oldVariant);
 assert.equal(primary.demand,demand);assert.equal(primary.greed,greed);assert.equal(primary.supplyPrice,calculator);
 assert.equal(primary.greed.modifiers.flat.find(row=>row.id==='external_margin').value,7);
 assert.equal(primary.demandPrice.demand,variant.demandPrice.demand);assert.deepEqual(primary.temporary,oldTemporary);
 assert.equal(live.peekCommodityData('a','lobster'),null);assert.equal(primary.lastPriceUpdate.triggerCommodityId,'luxury_goods');
 const again=live.updateStockpileAndPrice('a','lobster',{month:7,phase:'native-final-iteration'});
 assert.notEqual(again.diagnostics.random.seed,result.diagnostics.random.seed);assert.equal(again.diagnostics.noDemand,true);
 assert.notEqual(primary.stockpile,expectedStockpile);assert.equal(variant.stockpile,oldVariant);assert.equal(live.peekCommodityData('a','luxury_goods'),network);assert.equal(live.peekCommodityData('a','lobster'),null);
 assert.equal(primary.lastPriceUpdate.triggerCommodityId,'lobster');assert.ok(variant.playerDemandMod.mult.some(row=>row.id==='core'));
 assert.deepEqual(capture,before);assert.equal(live.snapshot().readyForAuthority,false);
 const invalid=new NativeLiveEconomyDraft(capture);invalid.reapplyMarketEconomicEffects('a');assert.throws(()=>invalid.updateStockpileAndPrice('a','luxury_goods',{month:7,phase:'per-tick'}),/stockpile phases/);assert.throws(()=>invalid.snapshot(),/must be discarded/);
});

