test('offline economic checkpoint resumes mid-task without replay and preserves lazy networks and shared objects',()=>{
 const capture=scheduledEconomyCapture(),before=structuredClone(capture),original=new NativeLiveEconomyDraft(capture);
 // Preserve an uninitialized cache, then an initialized cache belonging to the previous economy group.
 const cold=NativeLiveEconomyDraft.fromCheckpoint(JSON.parse(JSON.stringify(original.checkpoint())));
 assert.equal(cold.peekCommodityData('a','food'),null);assert.deepEqual(cold.snapshot(),original.snapshot());
 const during=cold.market('b');during.playerOwned=true;during.adminIsPlayer=true;for(const c of Object.values(during.commodities))c.maxDemand=0;
 let guarded=false;cold.modifyPopulationStability('b',()=>{guarded=true;assert.throws(()=>cold.checkpoint(),/between operations/);return 4;});assert.equal(guarded,true);
 original.reapplyEconomicEffects();original.runScheduledEconomyPass({lastIteration:false,paused:false});
 original.getCommodityData('a','food');original.market('a').econGroup='new-group';
 original.market('a').commodities.food.stockpile=-0;
 const cargo=original.market('a').retail.submarkets[0].cargo;cargo.slots.push(cargo.slots[1]);
 original.market('b').retail.submarkets.push({...original.market('a').retail.submarkets[0],cargo});
 original.beginScheduledEconomyPass({lastIteration:true,paused:false},()=>4);
 const roundTrip=live=>{
  const encoded=JSON.parse(JSON.stringify(live.checkpoint())),restored=NativeLiveEconomyDraft.fromCheckpoint(encoded,{readMaxOutposts:()=>4});
  assert.deepEqual(restored.snapshot(),live.snapshot());assert.deepEqual(restored.scheduledEconomyStatus(),live.scheduledEconomyStatus());
  for(const id of live.marketIds())for(const c of Object.keys(live.market(id).commodities))assert.deepEqual(restored.peekCommodityData(id,c),live.peekCommodityData(id,c));
  const a=restored.market('a'),b=restored.market('b');
  assert.equal(a.commodities.luxury_goods.demand,a.commodities.lobster.demand);
  assert.equal(a.production.productionQuality,a.economyBonuses.production_quality_mod);
  assert.equal(a.governedState.combatFleetSize,a.economyBonuses.combat_fleet_size_mult);
  assert.equal(a.retail.submarkets[0].cargo,b.retail.submarkets[0].cargo);
  assert.equal(a.retail.submarkets[0].cargo.slots[1],a.retail.submarkets[0].cargo.slots.at(-1));
  // Exported data and the resumed draft must not mutate the old transaction.
  assert.notEqual(a.population,live.market('a').population);assert.notEqual(a.production.productionQuality,live.market('a').production.productionQuality);
  return restored;
 };
 let resumed=roundTrip(original);assert.ok(Object.is(resumed.market('a').commodities.food.stockpile,-0));
 assert.throws(()=>NativeLiveEconomyDraft.fromCheckpoint(JSON.parse(JSON.stringify(original.checkpoint()))),/outpost getter/);
 // JSON graph corruption must not mutate the existing draft.
 const corrupt=JSON.parse(JSON.stringify(original.checkpoint()));corrupt.root.ref=corrupt.records.length;assert.throws(()=>NativeLiveEconomyDraft.fromCheckpoint(corrupt),/Dangling/);
 const shots=new Set();let remaining=100;
 while(original.scheduledEconomyStatus().status.phase!=='done'){
  assert.ok(remaining-->0);original.stepScheduledEconomyPass();resumed.stepScheduledEconomyPass();
  const s=original.scheduledEconomyStatus().status,key=s.phase==='main'?(s.commodityIndex===1?'commodity':null):s.phase;
  if(key&&!shots.has(key)){resumed=roundTrip(resumed);shots.add(key);}
 }
 assert.deepEqual(resumed.snapshot(),original.snapshot());assert.deepEqual(capture,before);
 const frozen=resumed.snapshot();resumed.stepScheduledEconomyPass();assert.deepEqual(resumed.snapshot(),frozen);
 // QualityData keeps a live StatBonus reference even after a completed-pass restore.
 const quality=Object.values(resumed.economyListenerSnapshot().shipQuality)[0];
 const producer=Object.values(quality).find(row=>row.marketId!==null);assert.ok(producer);
 resumed.market(producer.marketId).economyBonuses.production_quality_mod.flat.push({id:'after_restore',value:0.125});
 assert.ok(Object.values(Object.values(resumed.economyListenerSnapshot().shipQuality)[0]).some(row=>row.quality.flat.some(mod=>mod.id==='after_restore')));
 const failed=new NativeLiveEconomyDraft(capture);assert.throws(()=>failed.stepScheduledEconomyPass(),/No scheduled/);assert.throws(()=>failed.checkpoint(),/healthy draft/);
});


