function monthlyCaptureFixture(){
 const f=nativeSaveFixture();
 const node=(id,parent,body='',income=0,upkeep=0)=>'<FDNode z="'+id+'" n="Account" in="'+income+'" up="'+upkeep+'" tI="777" tU="888">'+(parent?'<p ref="'+parent+'"/>':'')+body+'</FDNode>';
 const current='<currentReport z="230010"><root z="230011" in="0" up="0" tI="777" tU="888"><c z="230012"><e><st>z-first</st>'+node('230013','230011','',12.5,1.25)+'</e><e><st>a-last</st>'+node('230014','230011','',0,2.25)+'</e></c></root><timestamp>0</timestamp><debt>0</debt><previousDebt>0</previousDebt></currentReport>';
 const previous='<previousReport z="230020"><root z="230021" in="0" up="0" tI="0" tU="0"/><timestamp>0</timestamp><debt>5</debt><previousDebt>0</previousDebt></previousReport>';
 const shared='<SharedData z="230001">'+current+previous+'</SharedData>';
 f.campaign=f.campaign.replace(/<playerFleet>[\s\S]*?<\/playerFleet>/,'<playerFleet cl="Flt" z="230030"><fD z="230031"><cargo z="230032"><c z="230033"><value>100.75</value></c></cargo></fD></playerFleet>');
 f.campaign=f.campaign.replace('</CampaignEngine>','<modAndPluginData z="230002"><persistentData z="230003"><e><st>core_CEFSSharedDataKey</st>'+shared+'</e></persistentData></modAndPluginData><listeners z="230004"><CoreScript z="230005"><shared ref="230001"/></CoreScript></listeners></CampaignEngine>');
 return {fixture:f,monthly:extract(f.campaign,f.descriptor).monthlyReportCapture};
}
