test('natural native receivers settle core resources stipend and log together, then resume without repeating month end',()=>{
 const capture=scheduledEconomyCapture(true),time=Date.UTC(2026,7,1);
 capture.monthlyReportCapture=monthlyCaptureFixture().monthly;capture.networkCapture.playerStatsRef='fixture-player-stats';
 capture.clock.timestamp=String(time);capture.clockCapture.state.timestamp=time;capture.clockCapture.readback.timestamp=time;capture.clockCapture.readback.date=new OriginalNativeClock(capture.clockCapture.state).date();
 capture.scheduler={state:'WAITING',elapsed:0,untilNext:3,iterationsLeft:0,previousMonth:7,queuedTaskCount:0};
 const cargo=(id,qty)=>({objectRef:id,unlimitedStacks:true,partials:null,slots:qty?[{objectRef:null,type:'RESOURCES',commodityId:'supplies',size:qty,maxSize:1000000,roundSize:false,cargoSpacePerUnit:1}]:[],spaceUsed:qty,extraCargoUsed:0,unresolved:[]});
 const local={objectRef:'local',classAlias:'LocalResourcesSubmarketPlugin',kind:'local-resources',marketId:'b',marketRef:'20',ended:null,tier:null,large:null,submarketSpecId:'local_resources',taken:cargo('taken',2),left:cargo('left',0)};
 capture.economyListenerCapture.objects.local=local;capture.economyListenerCapture.roster.push('local');capture.economyListenerCapture.managedRoster=['local','ignored','log','stipend'];
 capture.markets.find(m=>m.marketId==='b').retailCapture.otherSubmarkets.push({objectRef:'local-sub',specId:'local_resources',pluginRef:'local',source:{name:'Submarket',attributes:{},children:[],text:''}});
 const ids=['level','fleet','credits','supplies','fuel','cargo','crew','marines','colonies'];
 const coreRef=capture.monthlyReportCapture.coreRef;
 capture.economyNotificationCapture={scope:'native-saved-economy-notifications',schemaVersion:1,sectorRoster:[coreRef,'noop'],managedRoster:['local','ignored','log','stipend'],objects:{
  [coreRef]:{objectRef:coreRef,classAlias:'CoreScript',kind:'core'},noop:{objectRef:'noop',classAlias:'NearbyEventsEvent',kind:'native-empty-sector'},
  local:{objectRef:'local',classAlias:'LocalResourcesSubmarketPlugin',kind:'local-resources'},ignored:{objectRef:'ignored',classAlias:'OfficerManagerEvent',kind:'not-economy-tick'},
  log:{objectRef:'log',classAlias:'PlaythroughLog',kind:'playthrough-log',stats:ids.map(id=>({objectRef:'stat-'+id,id,kind:id,accrued:id==='credits'?['1']:[]})),data:[{timestamp:time-86400000,data:[['credits','1000']]}]},
  stipend:{objectRef:'stipend',classAlias:'GalatianAcademyStipend',kind:'academy-stipend',startTime:time-100*86400000},
 },academyFlag:{key:'$playerReceivingGAStipend',present:true,value:true},unresolved:[]};
 const saved=structuredClone(capture),live=new NativeLiveEconomyDraft(capture);live.reapplyEconomicEffects();live.market('b').playerOwned=true;
 // This fixture has no Ancyra. Expiry must remove the stipend rather than fabricate an eligible market.
 let productions=0,payrolls=0;
 const deps={isTutorialInProgress:()=>false,readFleetPayroll:()=>{payrolls++;return {crew:3,marines:2,officers:[]};},hasStorageAccess:()=>false,readStorageValues:()=>assert.fail('no fixture storage'),readAdministrators:()=>[],readIndustryName:(_m,id)=>id,
  doCustomProduction:state=>{productions++;const colonies=state.current.root.children.find(([key])=>key==='node_id_outposts')[1],bill=colonies.children.find(([key])=>key==='node_id_restocking')[1];assert.equal(bill.children.find(([key])=>key==='supplies')[1].upkeep,200);},
  hasPlayerFleet:()=>true,readPlayerLevel:()=>3,readFleetDeploymentPoints:()=>[1.5,2.5],readFleetCargoStat:kind=>({supplies:7.5,fuel:8.5,cargo:9.5,crew:3,marines:2})[kind]};
 const result=live.advanceNativeScheduledFrame(0,{settlement:deps});assert.equal(result.notificationMode,'native-receivers');assert.equal(productions,1);assert.equal(payrolls,1);
 const notification=live.economyNotificationSnapshot(),log=notification.objects.log;assert.equal(log.data.length,2);assert.equal(log.data[1].timestamp,time);assert.equal(new Map(log.data[1].data).get('credits'),'1');assert.equal(new Map(log.data[1].data).get('fleet'),'4');assert.ok(log.stats.every(s=>s.accrued.length===0));
 assert.deepEqual(notification.academyFlag,{key:'$playerReceivingGAStipend',present:false,value:null});assert.deepEqual(live.economyListenerSnapshot().managedRoster,['local','ignored','log']);assert.equal(live.economyListenerSnapshot().objects.local.taken.slots.length,0);assert.equal(live.monthlyAccountSnapshot().messages.length,1);
 const restored=NativeLiveEconomyDraft.fromCheckpoint(JSON.parse(JSON.stringify(live.checkpoint())));assert.deepEqual(restored.snapshot(),live.snapshot());
 restored.advanceNativeScheduledFrame(0,{settlement:deps});assert.equal(productions,1);assert.equal(payrolls,1);assert.deepEqual(restored.monthlyAccountSnapshot(),live.monthlyAccountSnapshot());assert.deepEqual(restored.economyNotificationSnapshot(),notification);assert.deepEqual(capture,saved);
 const manual=NativeLiveEconomyDraft.fromCheckpoint(live.checkpoint());assert.throws(()=>manual.reportCoreEconomyMonthEnd(deps),/Natural notification chain owns/);
 assert.throws(()=>restored.advanceNativeScheduledFrame(0,{notifications:{}}),/Cannot switch notification ownership/);
});


